  const handleSyncRecentPayments = async () => {
    setIsSyncingRecentPayments(true);
    try {
      const { data, error } = await supabase.functions.invoke('check-payment', {
        body: { action: 'sync-recent-club-payments' }
      });
      if (error) throw error;
      const reloaded = await fetchClubState();
      setState(reloaded);
      if (selectedSubForDetail) {
        const found = reloaded.subscriptions?.find((s) => s.id === selectedSubForDetail.id);
        if (found) setSelectedSubForDetail(found);
      }
      toast({
        title: 'Sincronização com Asaas Concluída!',
        description: data?.updatedCount > 0
          ? `${data.updatedCount} fatura(s) baixada(s) automaticamente! ${data.activatedCount} cadastro(s) ativado(s).`
          : 'Tudo atualizado! Todas as faturas confirmadas no Asaas já estão refletidas no sistema.',
      });
    } catch (err: any) {
      toast({
        title: 'Erro ao sincronizar baixas do Asaas',
        description: err?.message || 'Falha ao comunicar com o servidor.',
        variant: 'destructive',
      });
    } finally {
      setIsSyncingRecentPayments(false);
    }
  };

  // Sincronização periódica automática em segundo plano das faturas e baixas do Asaas
  useEffect(() => {
    let timer: any = null;
    let interval: any = null;
    const runAutoSync = async () => {
      try {
        const { data, error } = await supabase.functions.invoke('check-payment', {
          body: { action: 'sync-recent-club-payments' },
        });
        if (!error && data?.updatedCount > 0) {
          const reloaded = await fetchClubState();
          setState(reloaded);
          if (selectedSubForDetail) {
            const found = reloaded.subscriptions?.find((s) => s.id === selectedSubForDetail.id);
            if (found) setSelectedSubForDetail(found);
          }
        }
      } catch (e) {
        console.warn('[AdminClubEcosystem] Background Asaas sync warning:', e);
      }
    };

    timer = setTimeout(() => {
      runAutoSync();
      interval = setInterval(runAutoSync, 5 * 60 * 1000);
    }, 3000);

    return () => {
      clearTimeout(timer);
      if (interval) clearInterval(interval);
    };
  }, []);

  // Auto-sincronização de cobranças do Asaas ao abrir o Perfil Financeiro de um associado
  const lastAutoSyncedSubIdRef = useRef<string | null>(null);
  useEffect(() => {
    if (clientDetailTool === 'FINANCEIRO_CLIENTE' && selectedSubForDetail && selectedSubForDetail.holderCpf) {
      const subId = selectedSubForDetail.id;
      if (lastAutoSyncedSubIdRef.current === subId) return;
      lastAutoSyncedSubIdRef.current = subId;

      const syncCustomer = async () => {
        try {
          const cleanCpf = (selectedSubForDetail.holderCpf || '').replace(/\D/g, '');
          if (!cleanCpf) return;

          const firstAsaasId =
            selectedSubForDetail.invoices?.find((i) => i.asaasPaymentId)?.asaasPaymentId ||
            selectedSubForDetail.asaasPaymentId;

          const { data, error } = await supabase.functions.invoke('create-payment', {
            body: {
              action: 'list-customer-charges',
              cpf: cleanCpf,
              paymentId: firstAsaasId,
            },
          });

          if (error || !data?.success) return;
          const rawPayments: any[] = data.payments || [];
          if (rawPayments.length === 0) return;

          const validPayments = rawPayments.filter((p) => !p.deleted);
          let hasChanges = false;
          const currentInvs = [...(selectedSubForDetail.invoices || [])];

          for (const p of validPayments) {
            if (isAsaasReservationCharge(p.description)) continue;
            const isPaid = p.status === 'RECEIVED' || p.status === 'CONFIRMED' || p.status === 'RECEIVED_IN_CASH';
            const invIndex = currentInvs.findIndex(
              (i) =>
                !isClubInvoiceReservation(i) &&
                ((i.asaasPaymentId && i.asaasPaymentId === p.id) || (i.dueDate && p.dueDate && i.dueDate === p.dueDate))
            );
            if (invIndex >= 0) {
              const existing = currentInvs[invIndex];
              const newStatus = isPaid ? 'PAID' : p.status === 'OVERDUE' ? 'OVERDUE' : 'PENDING';
              if (existing.status !== newStatus || (!existing.paidAt && isPaid)) {
                currentInvs[invIndex] = {
                  ...existing,
                  status: newStatus,
                  paidAt: isPaid ? (p.clientPaymentDate || p.paymentDate || p.confirmedDate || new Date().toISOString()) : undefined,
                  asaasPaymentId: p.id,
                };
                hasChanges = true;
              }
            }
          }

          if (hasChanges) {
            const hasOverdueInvs = currentInvs.some(
              (i) => !isClubInvoiceReservation(i) && i.status === 'OVERDUE'
            );
            let nextStatus = selectedSubForDetail.status;
            let nextReason = selectedSubForDetail.inactivityReason;
            if (!hasOverdueInvs && (selectedSubForDetail.inactivityReason === 'MENSALIDADE_VENCIDA' || selectedSubForDetail.status === 'INACTIVE')) {
              nextStatus = 'ACTIVE';
              nextReason = undefined;
            }
            const updated: ClubSubscription = {
              ...selectedSubForDetail,
              status: nextStatus,
              inactivityReason: nextReason,
              inactivityReasons: nextReason ? selectedSubForDetail.inactivityReasons : undefined,
              invoices: currentInvs,
              updatedAt: new Date().toISOString(),
            };
            setSelectedSubForDetail(updated);
            if (state) {
              const nextState: ClubDatabaseState = {
                ...state,
                subscriptions: (state.subscriptions || []).map((s) => (s.id === updated.id ? updated : s)),
              };
              await persist(nextState);
            }
          }
        } catch (err) {
          console.warn('[AdminClubEcosystem] Auto sync customer error:', err);
        }
      };

      syncCustomer();
    }
  }, [clientDetailTool, selectedSubForDetail?.id]);

  const handleLoadAsaasCandidates = async () => {
    if (!state) return;
    setIsLoadingAsaasSync(true);
    setAsaasSyncError(null);
    try {
      const res = await fetchAsaasInstallmentCandidates(state);
      setAsaasSyncMeta({
        isProd: res.isProd,
        totalFound: res.totalFound,
        returnedCount: res.returnedCount,
        truncated: res.truncated,
      });
      setAsaasCandidates(res.candidates);

      const nextSelected: Record<string, boolean> = {};
      const nextTargets: Record<string, string> = {};
      const nextPayMap: Record<string, Record<string, boolean>> = {};

      res.candidates.forEach((cand) => {
        nextSelected[cand.customerId] = false; // Usuário revisa e escolhe quem sincronizar
        nextTargets[cand.customerId] = cand.matchedSubscriptionId || 'CREATE_PENDING';
        const payFlags: Record<string, boolean> = {};
        (cand.payments || []).forEach((p) => {
          payFlags[p.id] = !p.looksLikeReservation;
        });
        nextPayMap[cand.customerId] = payFlags;
      });

      setAsaasSelectedCustomers(nextSelected);
      setAsaasTargetMap(nextTargets);
      setAsaasPaymentSelectionMap(nextPayMap);
    } catch (err: any) {
      setAsaasSyncError(err?.message || 'Erro ao consultar parcelas ativas no Asaas.');
    } finally {
      setIsLoadingAsaasSync(false);
    }
  };

  const handleOpenAsaasSyncModal = () => {
    setIsAsaasSyncModalOpen(true);
    handleLoadAsaasCandidates();
  };

  const handleApplyAsaasSync = async (activateSelected: boolean = false) => {
    if (!state) return;
    const chosenCandidates = asaasCandidates.filter(
      (c) => asaasSelectedCustomers[c.customerId]
    );
    if (chosenCandidates.length === 0) {
      toast({
        title: 'Nenhum cliente selecionado',
        description: 'Marque ao menos um cliente na pré-visualização para importar as mensalidades.',
        variant: 'destructive',
      });
      return;
    }

    const selections = chosenCandidates
      .map((cand) => {
        const payFlags = asaasPaymentSelectionMap[cand.customerId] || {};
        const paymentIds = (cand.payments || [])
          .filter((p) => payFlags[p.id] !== false)
          .map((p) => p.id);
        return {
          candidate: cand,
          targetSubscriptionId: asaasTargetMap[cand.customerId] || cand.matchedSubscriptionId || 'CREATE_PENDING',
          paymentIds,
        };
      })
      .filter((s) => s.paymentIds.length > 0);

    if (selections.length === 0) {
      toast({
        title: 'Nenhuma parcela marcada',
        description: 'Os clientes marcados não têm parcelas selecionadas para importar.',
        variant: 'destructive',
      });
      return;
    }

    setIsApplyingAsaasSync(true);
    try {
      const result = await applySelectedAsaasSync(state, selections, { activateSelected });
      setState(result.state);
      toast({
        title: activateSelected
          ? 'Mensalidades Importadas e Cadastros Ativados!'
          : 'Mensalidades do Asaas Sincronizadas!',
        description: activateSelected
          ? `${result.updatedSubs} cliente(s) atualizado(s) • ${result.activatedSubs} cadastro(s) ativado(s) • ${result.importedInvoices} nova(s) parcela(s) • ${result.updatedInvoices} atualizada(s).`
          : `${result.updatedSubs} cliente(s) atualizado(s) • ${result.importedInvoices} nova(s) parcela(s) • ${result.updatedInvoices} atualizada(s). Nenhum cadastro foi ativado automaticamente.`,
      });
      setIsAsaasSyncModalOpen(false);
    } catch (err: any) {
      toast({
        title: 'Erro na sincronização com o Asaas',
        description: err?.message || 'Não foi possível salvar as mensalidades importadas.',
        variant: 'destructive',
      });
    } finally {
      setIsApplyingAsaasSync(false);
    }
  };

  // Sincronização completa com API do Labcard (e-mail, RG, sexo, endereço, validades, consultores, boletos)
  const [isLabcardSyncModalOpen, setIsLabcardSyncModalOpen] = useState(false);
  const [labcardHasServerCreds, setLabcardHasServerCreds] = useState<boolean>(false);
  const [labcardApiUser, setLabcardApiUser] = useState('');
  const [labcardApiPass, setLabcardApiPass] = useState('');
  const [isLoadingLabcardSync, setIsLoadingLabcardSync] = useState(false);
  const [labcardProgressText, setLabcardProgressText] = useState('');
