  const getAgeFromBirthDate = (birthDateStr?: string): number => {
    if (!birthDateStr) return -1;
    const parts = birthDateStr.split('-');
    if (parts.length < 3) return -1;
    const birth = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
    const today = new Date();
    let age = today.getFullYear() - birth.getFullYear();
    const m = today.getMonth() - birth.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birth.getDate())) {
      age--;
    }
    return age;
  };

  const getFilteredReportSubscriptions = () => {
    if (!state) return [];
    return (state.subscriptions || []).filter((sub) => {
      // 1. Período
      if (reportStartDate && sub.startDate < reportStartDate) return false;
      if (reportEndDate && sub.startDate > reportEndDate) return false;

      // 2. Cidade
      if (reportCity !== 'TODAS') {
        const subCity = (sub.addressCity || '').trim().toLowerCase();
        if (subCity !== reportCity.trim().toLowerCase()) return false;
      }

      // 3. Status
      if (reportStatus === 'ACTIVE' && sub.status !== 'ACTIVE') return false;
      if (reportStatus === 'INACTIVE' && sub.status === 'ACTIVE') return false;
      if (reportStatus === 'OVERDUE' && sub.status !== 'OVERDUE') return false;

      // 4. Plano
      if (reportPlanCode !== 'TODOS') {
        const hasPlan = sub.members.some((m) => m.modalityCode === reportPlanCode);
        if (!hasPlan) return false;
      }

      // 5. Cortesia
      const subIsCourtesy =
        sub.paymentMethod === 'COURTESY' ||
        sub.monthlyEquivalent === 0 ||
        sub.totalContractValue === 0;
      if (reportCourtesy === 'CORTESIA' && !subIsCourtesy) return false;
      if (reportCourtesy === 'PAGO' && subIsCourtesy) return false;

      // 6. Categoria (Titulares vs Dependentes)
      if (reportCategory === 'DEPENDENTES') {
        const hasDeps = sub.members.some((m) => m.role === 'DEPENDENTE');
        if (!hasDeps) return false;
      }

      // 7. Faixa Etária
      if (reportAgeGroup !== 'TODOS') {
        const matchesAge = sub.members.some((m) => {
          const age = getAgeFromBirthDate(m.birthDate);
          if (age < 0) return false;
          if (reportAgeGroup === 'KIDS') return age <= 12;
          if (reportAgeGroup === 'TEENS') return age >= 13 && age <= 17;
          if (reportAgeGroup === 'ADULTS') return age >= 18 && age <= 59;
          if (reportAgeGroup === 'SENIORS') return age >= 60;
          return true;
        });
        if (!matchesAge) return false;
      }

      return true;
    });
  };

  const getFilteredReportMembers = () => {
    if (!state?.subscriptions) return [];
    const results: { member: ClubMember; sub: ClubSubscription; isCourtesy: boolean }[] = [];
    const q = reportSearchQuery.trim().toLowerCase();

    state.subscriptions.forEach((sub) => {
      // 1. Período
      if (reportStartDate && sub.startDate < reportStartDate) return;
      if (reportEndDate && sub.startDate > reportEndDate) return;

      // 2. Cidade
      if (reportCity !== 'TODAS') {
        const subCity = (sub.addressCity || '').trim().toLowerCase();
        if (subCity !== reportCity.trim().toLowerCase()) return;
      }

      // 3. Status
      if (reportStatus === 'ACTIVE' && sub.status !== 'ACTIVE') return;
      if (reportStatus === 'INACTIVE' && sub.status === 'ACTIVE') return;
      if (reportStatus === 'OVERDUE' && sub.status !== 'OVERDUE') return;

      const subIsCourtesy =
        sub.paymentMethod === 'COURTESY' ||
        sub.monthlyEquivalent === 0 ||
        sub.totalContractValue === 0;

      (sub.members || []).forEach((m) => {
        // 4. Titulares vs Dependentes
        if (reportCategory === 'TITULARES' && m.role !== 'TITULAR') return;
        if (reportCategory === 'DEPENDENTES' && m.role !== 'DEPENDENTE') return;

        // 5. Plano
        if (reportPlanCode !== 'TODOS' && m.modalityCode !== reportPlanCode) return;

        // 6. Cortesia
        const memberIsCourtesy =
          subIsCourtesy ||
          m.monthlyValue === 0 ||
          m.modalityCode === 'KIDS' ||
          m.modalityCode === 'IDOSO_60' ||
          m.modalityCode === 'PCD_TEA';

        if (reportCourtesy === 'CORTESIA' && !memberIsCourtesy) return;
        if (reportCourtesy === 'PAGO' && memberIsCourtesy) return;

        // 7. Faixa Etária
        if (reportAgeGroup !== 'TODOS') {
          const age = getAgeFromBirthDate(m.birthDate);
          if (age >= 0) {
            if (reportAgeGroup === 'KIDS' && age > 12) return;
            if (reportAgeGroup === 'TEENS' && (age < 13 || age > 17)) return;
            if (reportAgeGroup === 'ADULTS' && (age < 18 || age > 59)) return;
            if (reportAgeGroup === 'SENIORS' && age < 60) return;
          }
        }

        // 8. Busca textual rápida no relatório
        if (q) {
          const matchName = (m.fullName || '').toLowerCase().includes(q);
          const matchCpf = cleanDigits(m.cpf || '').includes(cleanDigits(q));
          const matchCard = (m.cardNumber || '').toLowerCase().includes(q);
          const matchSub = (sub.holderName || '').toLowerCase().includes(q);
          if (!matchName && !matchCpf && !matchCard && !matchSub) return;
        }

        results.push({
          member: m,
          sub,
          isCourtesy: memberIsCourtesy,
        });
      });
    });

    return results;
  };

  const handleExportReportXlsx = (reportType: string) => {
    if (!state) return;
    let rows: Record<string, any>[] = [];
    if (reportType === 'CLIENTES') {
      const members = getFilteredReportMembers();
      rows = members.map(({ member, sub, isCourtesy }) => ({
        Cartao: member.cardNumber,
        Tipo: member.role === 'TITULAR' ? 'Titular' : 'Dependente',
        Nome: member.fullName,
        CPF: member.cpf || sub.holderCpf,
        Telefone: member.phone || sub.holderPhone,
        Email: sub.holderEmail || '',
        Plano: member.modalityName || sub.planSummaryLabel,
        Cidade: sub.addressCity || 'Ariquemes',
        UF: sub.addressState || 'RO',
        Cortesia: isCourtesy ? 'SIM (Gratuidade Oficial)' : 'NÃO (Plano Pago)',
        Valor: isCourtesy ? 0 : member.monthlyValue,
        Status: member.status || sub.status,
        Origem: sub.origin || 'SITE',
        TitularVinculado: member.role === 'DEPENDENTE' ? sub.holderName : '-',
        DataAdesao: formatDateBR(sub.startDate || sub.createdAt),
      }));
    } else if (reportType === 'EMPRESAS') {
      const baseFiltered = getFilteredReportSubscriptions();
      const targetSubs = baseFiltered.filter((s) => s.personType === 'PJ');
      rows = targetSubs.map((s) => ({
        Cartao: s.subscriptionCode,
        Empresa: s.holderName,
        CNPJ: s.holderCpf,
        Telefone: s.holderPhone,
        Email: s.holderEmail || '',
        Plano: s.planSummaryLabel,
        Ciclo: s.billingCycle === 'ANNUAL' ? 'Anual' : 'Mensal',
        Mensalidade: s.monthlyEquivalent,
        Status: s.status,
        Origem: s.origin,
        Consultor: s.consultantName || '',
        Integrantes: s.members.length,
        Cidade: s.addressCity,
        DataAdesao: formatDateBR(s.startDate),
      }));
    } else if (reportType === 'CONSULTORES' || reportType === 'INFLUENCER') {
      const role = reportType === 'INFLUENCER' ? 'INFLUENCER' : 'CONSULTOR';
      rows = state.consultants
        .filter((c) => c.role === role)
        .map((c) => ({
          Nome: c.name,
          Funcao: c.role,
          CPF: c.cpf,
          Telefone: c.phone,
          Codigo: c.referralCode,
          Comissao_Pct: c.commissionPercent,
          Status: c.status,
        }));
    } else {
      rows = cashFlowSummary.entries.map((e) => ({
        Data: formatDateBR(e.date),
        Tipo: e.type === 'IN' ? 'ENTRADA' : 'SAIDA',
        Categoria: e.category,
        Descricao: e.description,
        Valor: e.amount,
        Forma_Pagto: e.paymentMethod,
      }));
    }
    const ws = XLSX.utils.json_to_sheet(rows);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, `Relatorio_${reportType}`);
    XLSX.writeFile(wb, `Relatorio_Lessa_Club_${reportType}.xlsx`);
  };

  // Quick search results
  const quickSearchResults = useMemo(() => {
    if (!state || !quickQuery.trim()) return [];
    return findMemberOrSubscriptionByQuery(state, quickQuery);
  }, [state, quickQuery]);

  // Calculate preview monthly total in Manual Registration Modal
  const calculatedManualMonthly = useMemo(() => {
    if (!state) return 0;
    const holderMod = (state.modalities || []).find((m) => m.code === holderModalityCode);
    let sum = holderMod
      ? cycle === 'ANNUAL'
        ? holderMod.annualInstallment
        : holderMod.monthlyPrice
      : 0;
    for (const dep of manualDependents) {
      const m = (state.modalities || []).find((mod) => mod.code === dep.modalityCode);
      if (m) {
        sum += cycle === 'ANNUAL' ? m.annualInstallment : m.monthlyPrice;
      }
    }
    return Number(sum.toFixed(2));
  }, [state, holderModalityCode, manualDependents, cycle]);

  const currentDetailSubIdRef = useRef<string | null>(null);

  useEffect(() => {
    if (!selectedSubForDetail) {
      currentDetailSubIdRef.current = null;
      return;
    }

    const isNewClient = currentDetailSubIdRef.current !== selectedSubForDetail.id;

    if (isNewClient) {
      currentDetailSubIdRef.current = selectedSubForDetail.id;

      if (selectedSubForDetail.status === 'ACTIVE') {
        setSituacaoLiberar('SIM');
        setSituacaoInativar('NAO');
      } else if (selectedSubForDetail.status === 'PENDING_TRANSFER') {
        setSituacaoLiberar('NAO');
        setSituacaoInativar('NAO');
      } else {
        setSituacaoLiberar('NAO');
        setSituacaoInativar('SIM');
      }
      const initReason = selectedSubForDetail.inactivityReason || 'MENSALIDADE_VENCIDA';
      setSituacaoMotivoInativo(initReason);
      if (selectedSubForDetail.inactivityReasons && selectedSubForDetail.inactivityReasons.length > 0) {
        setSituacaoMotivosInativo(selectedSubForDetail.inactivityReasons);
      } else if (initReason === 'MENSALIDADE_E_DOCUMENTOS') {
        setSituacaoMotivosInativo(['MENSALIDADE_VENCIDA', 'FALTA_DOCUMENTOS']);
      } else {
        setSituacaoMotivosInativo([initReason]);
      }
      setSituacaoNotasInativo(selectedSubForDetail.inactivityNotes || '');
      setTempExpirationDate(selectedSubForDetail.endDate || '2027-10-31');
      const rawPlanDesc = selectedSubForDetail.planSummaryLabel || '';
      const titularMember =
        selectedSubForDetail.members.find((m) => m.role === 'TITULAR') ||
        selectedSubForDetail.members[0];
      const memberModCode = titularMember?.modalityCode || '';
      const memberModName = titularMember?.modalityName || '';

      const detectedModalityCode = detectModalityCodeFromPlanDescription(
        rawPlanDesc || memberModName,
        memberModCode,
        state?.modalities
      );

      setEditClientData({
        holderName: selectedSubForDetail.holderName || '',
        holderCpf: selectedSubForDetail.holderCpf || '',
        holderRg: selectedSubForDetail.holderRg || '',
        holderBirthDate: selectedSubForDetail.holderBirthDate || '',
        holderSex: selectedSubForDetail.holderSex || '',
        holderMaritalStatus: selectedSubForDetail.holderMaritalStatus || '',
        holderPhone: selectedSubForDetail.holderPhone || '',
        holderEmail: selectedSubForDetail.holderEmail || '',
        consultantName: selectedSubForDetail.consultantName || '',
        influencerName: selectedSubForDetail.influencerName || '',
        addressCep: selectedSubForDetail.addressCep || '76870-000',
        addressStreet: selectedSubForDetail.addressStreet || '',
        addressNumber: selectedSubForDetail.addressNumber || '',
        addressComplement: selectedSubForDetail.addressComplement || '',
        addressNeighborhood: selectedSubForDetail.addressNeighborhood || '',
        addressCity: selectedSubForDetail.addressCity || 'Ariquemes',
        addressState: selectedSubForDetail.addressState || 'RO',
        vehicleModel: selectedSubForDetail.vehicleModel || '',
        vehicleBrand: selectedSubForDetail.vehicleBrand || '',
        vehiclePlate: selectedSubForDetail.vehiclePlate || '',
        vehicleColor: selectedSubForDetail.vehicleColor || '',
        vehicleStickerPhotoUrl: selectedSubForDetail.vehicleStickerPhotoUrl || '',
        vehicleStickerPhotoName: selectedSubForDetail.vehicleStickerPhotoName || '',
        notes: selectedSubForDetail.notes || '',
        dueDay: selectedSubForDetail.dueDay || 10,
        billingCycle: selectedSubForDetail.billingCycle || 'ANNUAL',
        monthlyEquivalent: selectedSubForDetail.monthlyEquivalent ?? 0,
        planSummaryLabel: selectedSubForDetail.planSummaryLabel || '',
        modalityCode: detectedModalityCode || '',
        endDate: selectedSubForDetail.endDate || '',
      });

      const draftMap: Record<string, string> = {};
      (selectedSubForDetail.members || []).forEach((m) => {
        draftMap[m.id] = m.expirationDate || '';
      });
      setDepExpDrafts(draftMap);
      setLastRegistrationChangeBox(null);
      setSelectedClientInvoiceIdsForDelete([]);
      setEditingClientInvoiceId(null);
      setShowFaturaAvulsaForm(false);
      markClubSubAsSeen(selectedSubForDetail.id);
      if (typeof window !== 'undefined') {
        window.scrollTo({ top: 0, behavior: 'smooth' });
      }

      // Restauração atômica de dados e anexos permanentes salvos no Supabase e no IndexedDB
      const lookupCode = selectedSubForDetail.subscriptionCode || selectedSubForDetail.holderCpf;
      if (lookupCode) {
        loadMemberPermanentDocs(lookupCode).then((permData) => {
          if (permData) {
            setEditClientData((prev) => ({
              ...prev,
              holderEmail: prev.holderEmail.trim() ? prev.holderEmail : (permData.holderEmail || prev.holderEmail),
              addressCep: (prev.addressCep.trim() && prev.addressCep !== '76870-000') ? prev.addressCep : (permData.addressCep || prev.addressCep),
              addressStreet: prev.addressStreet.trim() ? prev.addressStreet : (permData.addressStreet || prev.addressStreet),
              addressNeighborhood: prev.addressNeighborhood.trim() ? prev.addressNeighborhood : (permData.addressNeighborhood || prev.addressNeighborhood),
              holderRg: prev.holderRg.trim() ? prev.holderRg : (permData.holderRg || prev.holderRg),
              holderBirthDate: prev.holderBirthDate || permData.holderBirthDate,
              endDate: prev.endDate || permData.endDate,
            }));
            if (permData.attachments && permData.attachments.length > (selectedSubForDetail.attachments?.length || 0)) {
              setSelectedSubForDetail((prevSub) => {
                if (!prevSub) return prevSub;
                return applyPermanentDocsToSub(prevSub, permData);
              });
            }
          }
        }).catch(() => {});
      }
    } else {
      // Quando for o MESMO cliente (navegação entre abas ou ações secundárias),
      // PRESERVA RIGOROSAMENTE todas as alterações e textos preenchidos pelo usuário!
      setEditClientData((prev) => ({
        ...prev,
        holderName: prev.holderName.trim() ? prev.holderName : (selectedSubForDetail.holderName || ''),
        holderEmail: prev.holderEmail.trim() ? prev.holderEmail : (selectedSubForDetail.holderEmail || ''),
        holderPhone: prev.holderPhone.trim() ? prev.holderPhone : (selectedSubForDetail.holderPhone || ''),
        addressCep: prev.addressCep.trim() ? prev.addressCep : (selectedSubForDetail.addressCep || '76870-000'),
        addressStreet: prev.addressStreet.trim() ? prev.addressStreet : (selectedSubForDetail.addressStreet || ''),
        addressNumber: prev.addressNumber.trim() ? prev.addressNumber : (selectedSubForDetail.addressNumber || ''),
        addressComplement: prev.addressComplement.trim() ? prev.addressComplement : (selectedSubForDetail.addressComplement || ''),
        addressNeighborhood: prev.addressNeighborhood.trim() ? prev.addressNeighborhood : (selectedSubForDetail.addressNeighborhood || ''),
        addressCity: prev.addressCity.trim() ? prev.addressCity : (selectedSubForDetail.addressCity || 'Ariquemes'),
        addressState: prev.addressState.trim() ? prev.addressState : (selectedSubForDetail.addressState || 'RO'),
        vehicleModel: prev.vehicleModel.trim() ? prev.vehicleModel : (selectedSubForDetail.vehicleModel || ''),
        vehicleBrand: prev.vehicleBrand.trim() ? prev.vehicleBrand : (selectedSubForDetail.vehicleBrand || ''),
        vehiclePlate: prev.vehiclePlate.trim() ? prev.vehiclePlate : (selectedSubForDetail.vehiclePlate || ''),
        vehicleColor: prev.vehicleColor.trim() ? prev.vehicleColor : (selectedSubForDetail.vehicleColor || ''),
        notes: prev.notes.trim() ? prev.notes : (selectedSubForDetail.notes || ''),
      }));
    }
  }, [selectedSubForDetail?.id]);

  const isFirstMountFiltersRef = useRef(true);
  useEffect(() => {
    if (isFirstMountFiltersRef.current) {
      isFirstMountFiltersRef.current = false;
      return;
    }
    setSelectedSubForDetail(null);
  }, [
    activeTab,
    subStatusFilter,
    personFilter,
    originFilter,
    financeSubView,
    reportSubView,
    configSection,
    perfilSection,
  ]);

  useEffect(() => {
    if (selectedSubForDetail && state?.subscriptions) {
      const fresh = state.subscriptions.find((s) => s.id === selectedSubForDetail.id);
      if (fresh && fresh !== selectedSubForDetail) {
        setSelectedSubForDetail(fresh);
      }
    }
  }, [state?.subscriptions]);

  const handleSaveClientRegistrationEdits = async () => {
    if (!state || !selectedSubForDetail || isSavingClientRegistration) return;

    const rawCpf = editClientData.holderCpf.trim();
    if (rawCpf && selectedSubForDetail.personType === 'PF' && !isValidCpf(rawCpf)) {
      toast({
        title: 'CPF do Titular Inválido',
        description: 'Por favor, informe um CPF válido com 11 dígitos para o titular.',
        variant: 'destructive',
      });
      return;
    }
    if (rawCpf && selectedSubForDetail.personType === 'PJ' && !isValidCnpj(rawCpf)) {
      toast({
        title: 'CNPJ da Empresa Inválido',
        description: 'Por favor, informe um CNPJ válido com 14 dígitos para a empresa.',
        variant: 'destructive',
      });
      return;
    }

    setIsSavingClientRegistration(true);
    try {
      const prevStatus = selectedSubForDetail.status;
      const chosenModality = (state.modalities || []).find(
        (mod) => mod.code === editClientData.modalityCode
      );
      const isSemPlano = editClientData.modalityCode === 'SEM_PLANO';
      const isCorporateCourtesy = editClientData.modalityCode === 'CORPORATE';
      const isPublicidade = editClientData.modalityCode === 'PUBLICIDADE';

      const isLiberandoManualmente = situacaoLiberar === 'SIM';
      const targetStatus: ClubSubscription['status'] = isSemPlano
        ? 'INACTIVE'
        : situacaoInativar === 'SIM'
        ? 'INACTIVE'
        : isLiberandoManualmente
        ? 'ACTIVE'
        : selectedSubForDetail.status === 'PENDING_TRANSFER'
        ? 'PENDING_TRANSFER'
        : selectedSubForDetail.status === 'ACTIVE'
        ? 'ACTIVE'
        : selectedSubForDetail.status || 'INACTIVE';

      // Validação estrita do Plano Lessa Family:
      // O plano é para o dono do carro e dependentes apenas cônjuge e filhos.
      // O plano só será ativado após ter os documentos de cada dependente anexado e a foto do carro adesivado.
      const isLessaFamily =
        isPublicidade ||
        selectedSubForDetail.contractType === 'FAMILY_PUBLICIDADE' ||
        (selectedSubForDetail.planSummaryLabel && /family|adesiv/i.test(selectedSubForDetail.planSummaryLabel));

      if (isLessaFamily && targetStatus === 'ACTIVE') {
        const hasCarPhoto = Boolean(
          editClientData.vehicleStickerPhotoUrl ||
          selectedSubForDetail.vehicleStickerPhotoUrl ||
          (selectedSubForDetail.attachments || []).some((a) => /carro|adesiv/i.test(a.name))
        );
        if (!hasCarPhoto) {
          toast({
            title: 'Não é possível ativar o Plano Lessa Family',
            description: 'É obrigatório anexar a foto do carro adesivado antes de ativar o plano.',
            variant: 'destructive',
          });
          setIsSavingClientRegistration(false);
          return;
        }

        const deps = (selectedSubForDetail.members || []).filter((m) => m.role === 'DEPENDENTE');
        const invalidKinshipDep = deps.find((m) => {
          const k = (m.kinship || '').trim().toLowerCase();
          return k && !k.includes('cônjuge') && !k.includes('conjuge') && !k.includes('filho') && !k.includes('filha');
        });
        if (invalidKinshipDep) {
          toast({
            title: 'Parentesco Inválido no Lessa Family',
            description: `O dependente ${invalidKinshipDep.fullName} possui parentesco "${invalidKinshipDep.kinship}". No Plano Lessa Family apenas cônjuge e filhos são permitidos.`,
            variant: 'destructive',
          });
          setIsSavingClientRegistration(false);
          return;
        }

        const missingDocDep = deps.find((m) => !m.documentProofUrl && (!m.attachments || m.attachments.length === 0));
        if (missingDocDep) {
          toast({
            title: 'RG Obrigatório do Dependente',
            description: `O dependente ${missingDocDep.fullName} precisa do documento (RG com foto) anexado para validação e ativação do plano.`,
            variant: 'destructive',
          });
          setIsSavingClientRegistration(false);
          return;
        }
      }

      if (isSemPlano) {
        setSituacaoLiberar('NAO');
        setSituacaoInativar('SIM');
      }

      const nextEndDate =
        editClientData.endDate.trim() ||
        tempExpirationDate.trim() ||
        selectedSubForDetail.endDate ||
        '2027-10-31';
      const nextValidityLabel = getValidityLabelFromDate(nextEndDate);
      const parsedEditMonthly = Number(String(editClientData.monthlyEquivalent).replace(',', '.'));
      const monthlyVal =
        isSemPlano || isCorporateCourtesy || isPublicidade
          ? 0
          : Number.isFinite(parsedEditMonthly) && parsedEditMonthly >= 0
          ? parsedEditMonthly
          : selectedSubForDetail.monthlyEquivalent;
      const cycleSuffix =
        editClientData.billingCycle === 'ANNUAL' ? '(Anual)' : '(Mensal)';
      const updatedSub: ClubSubscription = {
        ...selectedSubForDetail,
        status: targetStatus,
        contractType: isPublicidade
          ? 'FAMILY_PUBLICIDADE'
          : selectedSubForDetail.contractType,
        paymentMethod: isCorporateCourtesy || isPublicidade
          ? 'COURTESY'
          : selectedSubForDetail.paymentMethod,
        endDate: nextEndDate,
        holderName: editClientData.holderName.trim() || selectedSubForDetail.holderName,
        holderCpf: editClientData.holderCpf.trim() || selectedSubForDetail.holderCpf,
        holderRg: editClientData.holderRg.trim(),
        holderBirthDate: editClientData.holderBirthDate,
        holderSex: editClientData.holderSex,
        holderMaritalStatus: editClientData.holderMaritalStatus,
        holderPhone: editClientData.holderPhone.trim(),
        holderEmail: editClientData.holderEmail.trim() || selectedSubForDetail.holderEmail || '',
        consultantName: editClientData.consultantName.trim() || selectedSubForDetail.consultantName || '',
        influencerName: editClientData.influencerName.trim() || selectedSubForDetail.influencerName || '',
        addressCep: editClientData.addressCep.trim() || selectedSubForDetail.addressCep || '76870-000',
        addressStreet: editClientData.addressStreet.trim() || selectedSubForDetail.addressStreet || '',
        addressNumber: editClientData.addressNumber.trim() || selectedSubForDetail.addressNumber || '',
        addressComplement: editClientData.addressComplement.trim() || selectedSubForDetail.addressComplement || '',
        addressNeighborhood: editClientData.addressNeighborhood.trim() || selectedSubForDetail.addressNeighborhood || '',
        addressCity: editClientData.addressCity.trim() || selectedSubForDetail.addressCity || 'Ariquemes',
        addressState: editClientData.addressState.trim() || selectedSubForDetail.addressState || 'RO',
        vehicleModel: editClientData.vehicleModel.trim(),
        vehicleBrand: editClientData.vehicleBrand.trim(),
        vehiclePlate: editClientData.vehiclePlate.trim().toUpperCase(),
        vehicleColor: editClientData.vehicleColor.trim(),
        vehicleStickerPhotoUrl: editClientData.vehicleStickerPhotoUrl || selectedSubForDetail.vehicleStickerPhotoUrl,
        vehicleStickerPhotoName: editClientData.vehicleStickerPhotoName || selectedSubForDetail.vehicleStickerPhotoName,
        notes: editClientData.notes.trim(),
        dueDay: Number(editClientData.dueDay) || 10,
        billingCycle: editClientData.billingCycle,
        monthlyEquivalent: monthlyVal,
        totalContractValue:
          isSemPlano || isCorporateCourtesy || isPublicidade
            ? 0
            : editClientData.billingCycle === 'ANNUAL'
            ? Number((monthlyVal * 12).toFixed(2))
            : monthlyVal,
        planSummaryLabel:
          editClientData.planSummaryLabel.trim() ||
          selectedSubForDetail.planSummaryLabel,
        members: selectedSubForDetail.members.map((m) =>
          m.role === 'TITULAR'
            ? {
                ...m,
                modalityCode: chosenModality ? chosenModality.code : m.modalityCode,
                modalityName: chosenModality ? chosenModality.name : m.modalityName,
                planCycleLabel: chosenModality
                  ? chosenModality.isFreeTier
                    ? chosenModality.name
                    : `${chosenModality.name} ${cycleSuffix}`
                  : m.planCycleLabel,
                monthlyValue: chosenModality ? monthlyVal : m.monthlyValue,
                frontCardUrl: isPublicidade
                  ? '/cards/29.png'
                  : chosenModality?.frontCardUrl || m.frontCardUrl,
                backCardUrl: isPublicidade
                  ? '/cards/33.png'
                  : chosenModality?.backCardUrl || m.backCardUrl,
                fullName:
                  editClientData.holderName.trim() || m.fullName,
                cpf: editClientData.holderCpf.trim() || m.cpf,
                rg: editClientData.holderRg.trim() || m.rg,
                birthDate: editClientData.holderBirthDate || m.birthDate,
                sex: editClientData.holderSex || m.sex,
                phone: editClientData.holderPhone.trim() || m.phone,
                status: targetStatus,
                inactivityReason: targetStatus === 'ACTIVE' ? undefined : (situacaoMotivoInativo || 'MENSALIDADE_VENCIDA'),
                inactivityReasons: targetStatus === 'ACTIVE' ? undefined : situacaoMotivosInativo,
                inactivityNotes: targetStatus === 'ACTIVE' ? undefined : (situacaoNotasInativo || undefined),
                documentVerified: memberHasProofUploaded(m, selectedSubForDetail) ? m.documentVerified : false,
                documentStatus: memberHasProofUploaded(m, selectedSubForDetail) ? m.documentStatus : undefined,
                manualStatusOverride: true,
                expirationDate: nextEndDate || m.expirationDate,
                validityLabel: nextValidityLabel || m.validityLabel,
              }
            : {
                ...m,
                // Se o dependente estava como "Sem Plano", herda automaticamente o plano e a arte do titular
                modalityCode: (!m.modalityCode || m.modalityCode === 'SEM_PLANO') && chosenModality && !isSemPlano ? chosenModality.code : m.modalityCode,
                modalityName: (!m.modalityName || /^sem plano$/i.test(m.modalityName.trim()) || m.modalityCode === 'SEM_PLANO') && chosenModality && !isSemPlano ? chosenModality.name : m.modalityName,
                planCycleLabel: (!m.planCycleLabel || /^sem plano$/i.test(m.planCycleLabel.trim()) || m.modalityCode === 'SEM_PLANO') && chosenModality && !isSemPlano ? chosenModality.name : m.planCycleLabel,
                frontCardUrl:
                  (!m.modalityCode || m.modalityCode === 'SEM_PLANO' || m.frontCardUrl === '/cards/13.png') && chosenModality && !isSemPlano
                    ? (isPublicidade ? '/cards/30.png' : chosenModality.dependentFrontCardUrl || chosenModality.frontCardUrl || m.frontCardUrl)
                    : m.frontCardUrl,
                backCardUrl:
                  (!m.modalityCode || m.modalityCode === 'SEM_PLANO') && chosenModality && !isSemPlano
                    ? (isPublicidade ? '/cards/33.png' : chosenModality.dependentBackCardUrl || chosenModality.backCardUrl || m.backCardUrl)
                    : m.backCardUrl,
                // Preserva o status individual do dependente quando o titular já permanece ATIVO;
                // se o cadastro mudou para INATIVO, sincroniza com a alteração solicitada.
                status:
                  prevStatus !== targetStatus || targetStatus !== 'ACTIVE'
                    ? targetStatus
                    : m.status,
                inactivityReason: targetStatus === 'ACTIVE' ? undefined : (situacaoMotivoInativo || 'MENSALIDADE_VENCIDA'),
                inactivityReasons: targetStatus === 'ACTIVE' ? undefined : situacaoMotivosInativo,
                inactivityNotes: targetStatus === 'ACTIVE' ? undefined : (situacaoNotasInativo || undefined),
                documentVerified: memberHasProofUploaded(m, selectedSubForDetail) ? m.documentVerified : false,
                documentStatus: memberHasProofUploaded(m, selectedSubForDetail) ? m.documentStatus : undefined,
                manualStatusOverride: true,
                expirationDate: depExpDrafts[m.id] !== undefined ? (depExpDrafts[m.id] || undefined) : m.expirationDate,
                validityLabel: (depExpDrafts[m.id] || m.expirationDate)
                  ? getValidityLabelFromDate((depExpDrafts[m.id] || m.expirationDate)!, m.validityLabel)
                  : nextValidityLabel || m.validityLabel,
              }
        ),
        inactivityReason: targetStatus === 'ACTIVE' ? undefined : (situacaoMotivoInativo || 'MENSALIDADE_VENCIDA'),
        inactivityReasons: targetStatus === 'ACTIVE' ? undefined : situacaoMotivosInativo,
        inactivityNotes: targetStatus === 'ACTIVE' ? undefined : (situacaoNotasInativo || undefined),
        updatedAt: new Date().toISOString(),
        transferCompleted: selectedSubForDetail.transferCompleted !== undefined 
          ? selectedSubForDetail.transferCompleted 
          : (targetStatus === 'ACTIVE'),
        manuallyConfirmedTransfer: selectedSubForDetail.manuallyConfirmedTransfer !== undefined 
          ? selectedSubForDetail.manuallyConfirmedTransfer 
          : (targetStatus === 'ACTIVE'),
        manualStatusOverride: true,
        isModifiedFromSeed: true,
        transferredAt: selectedSubForDetail.transferredAt || (targetStatus === 'ACTIVE' ? new Date().toISOString() : undefined),
      };

      // Atualiza imediatamente na tela antes da persistência
      setSelectedSubForDetail(updatedSub);

      const nextState: ClubDatabaseState = {
        ...state,
        subscriptions: (state.subscriptions || []).map((s) =>
          s.id === updatedSub.id ? updatedSub : s
        ),
      };

      // Grava no estado e aguarda a confirmação de nuvem
      await persist(nextState, { waitForCloud: true });

      // Blindagem atômica dedicada permanente no Supabase (club_member_docs_*) e no IndexedDB:
      // Impede definitivamente qualquer perda de anexos, e-mail, CEP e datas por merges futuros.
      const permCode = updatedSub.subscriptionCode || updatedSub.holderCpf;
      if (permCode) {
        saveMemberPermanentDocs(permCode, updatedSub).catch((err) => {
          console.warn('[AdminClubEcosystem] Aviso ao salvar documento permanente:', err);
        });
      }

      // Blindagem definitiva: persiste os cartões no conjunto de cartões confirmados pelo administrador
      if (updatedSub.subscriptionCode) {
        markCardAsAdminConfirmed(updatedSub.subscriptionCode, targetStatus === 'ACTIVE');
      }
      if (updatedSub.members) {
        updatedSub.members.forEach((m) => {
          if (m.cardNumber) {
            markCardAsAdminConfirmed(m.cardNumber, (m.status || targetStatus) === 'ACTIVE');
          }
        });
      }

      setEditClientData((prev) => ({ ...prev, endDate: nextEndDate }));
      setTempExpirationDate(nextEndDate);
      if (targetStatus === 'ACTIVE') {
        setSituacaoLiberar('SIM');
        setSituacaoInativar('NAO');
      } else if (targetStatus === 'INACTIVE') {
        setSituacaoLiberar('NAO');
        setSituacaoInativar('SIM');
      }

      const syncStatus = getCloudSyncStatus();
      const isCloudOk = syncStatus.status === 'SYNCED';

      const prevLabel = prevStatus === 'ACTIVE' ? 'ATIVO' : 'INATIVO';
      const newLabel = targetStatus === 'ACTIVE' ? 'ATIVO' : 'INATIVO';
      const statusChanged = prevStatus !== targetStatus;
      const nowTime = new Date().toLocaleTimeString('pt-BR');
      const feedbackMsg = statusChanged
        ? `Alteração realizada no cadastro de ${updatedSub.holderName}: situação alterada de ${prevLabel} para ${newLabel}. Expiração: ${formatDateBR(nextEndDate)}.${isCloudOk ? ' (Gravado na Nuvem ✓)' : ' (Aviso: Guardado no navegador, reenviando para a nuvem...)'}`
        : `Alterações do cadastro de ${updatedSub.holderName} salvas com sucesso (Situação: ${newLabel} • Expiração: ${formatDateBR(nextEndDate)}).${isCloudOk ? ' (Gravado na Nuvem ✓)' : ' (Aviso: Guardado no navegador, reenviando para a nuvem...)'}`;
      setLastRegistrationChangeBox({
        title: !isCloudOk
          ? 'Salvo Localmente (Aguardando Nuvem)'
          : statusChanged
          ? `Alteração no cadastro realizada (${prevLabel} → ${newLabel})`
          : 'Cadastro salvo e gravado na Nuvem!',
        detail: feedbackMsg,
        isActive: targetStatus === 'ACTIVE',
        changedAt: nowTime,
      });
      setStatusChangeFeedbackModal({
        title: 'Alteração realizada no cadastro!',
        previousStatusLabel: statusChanged ? prevLabel : undefined,
        newStatusLabel: newLabel,
        subjectName: `${updatedSub.holderName} (Cartão #${updatedSub.subscriptionCode})`,
        expirationDate: nextEndDate,
        detail: feedbackMsg,
        isActive: targetStatus === 'ACTIVE',
      });
      toast({
        title: 'Cadastro do cliente atualizado com sucesso!',
        description: `${updatedSub.holderName} (#${updatedSub.subscriptionCode}) — Status: ${
          targetStatus === 'ACTIVE' ? 'ATIVO (LIBERADO)' : 'INATIVO'
        }`,
      });
    } catch (err: any) {
      console.error('[AdminClubEcosystem] Erro ao salvar cadastro do cliente:', err);
      toast({
        title: 'Aviso ao salvar cadastro',
        description: 'Os dados foram preservados com sucesso no navegador.',
      });
    } finally {
      setIsSavingClientRegistration(false);
    }
  };

  // Função para vincular múltiplos dependentes selecionados de uma vez só
  const handleAttachMultiplePersonsAsDependents = async (
    persons: Array<{
      fullName: string;
      cpf?: string;
      cardNumber?: string;
      birthDate?: string;
      phone?: string;
      modalityCode?: string;
      sourceSubscriptionId?: string;
    }>
  ) => {
    if (!state || !selectedSubForDetail || persons.length === 0) return;
    setAttachingPersonLoading(true);

    try {
      const targetSub = selectedSubForDetail;
      const isPlanAllowingDeps = doesPlanAllowDependents(
        targetSub.planSummaryLabel || targetSub.members[0]?.modalityCode
      );
      if (!isPlanAllowingDeps) {
        toast({
          title: 'Plano Individual',
          description:
            'Este plano é estritamente individual (Student, Professor, Servidor, Kids, TEA/PCD ou Vitalício) e não aceita dependentes. Apenas os planos Lessa Family e Lessa Club permitem dependentes.',
          variant: 'destructive',
        });
        setAttachingPersonLoading(false);
        return;
      }

      let currentMembers = [...targetSub.members];
      let nextSubs = [...(state.subscriptions || [])];
      let nextDeleted = [...(state.deletedSubscriptionIds || [])];
      const addedNames: string[] = [];

      for (let i = 0; i < persons.length; i++) {
        const person = persons[i];
        const cleanName = person.fullName.trim();
        const cleanCpf = person.cpf ? formatCpf(person.cpf) : '';
        const cardNum = person.cardNumber || String(Number(targetSub.subscriptionCode) + currentMembers.length);

        // Verifica se a pessoa já está nesta assinatura
        const alreadyInSub = currentMembers.some(
          (m) =>
            m.cardNumber === cardNum ||
            (cleanCpf && m.cpf && m.cpf.replace(/\D/g, '') === cleanCpf.replace(/\D/g, '')) ||
            m.fullName.trim().toLowerCase() === cleanName.toLowerCase()
        );
        if (alreadyInSub) continue;

        const titularMem = targetSub.members.find((x) => x.role === 'TITULAR') || targetSub.members[0];
        const isPersonSemPlano = !person.modalityCode || person.modalityCode === 'SEM_PLANO';
        const isTitularFamilyPub =
          targetSub.contractType === 'FAMILY_PUBLICIDADE' ||
          titularMem?.modalityCode === 'PUBLICIDADE' ||
          Boolean(targetSub.planSummaryLabel && /publicidade|family/i.test(targetSub.planSummaryLabel));

        const preferredCode = isPersonSemPlano
          ? (isTitularFamilyPub ? 'PUBLICIDADE' : (titularMem?.modalityCode && titularMem.modalityCode !== 'SEM_PLANO' ? titularMem.modalityCode : 'ADULTO'))
          : person.modalityCode;

        const mod =
          (state.modalities || []).find((m) => m.code === preferredCode) ||
          (state.modalities || []).find((m) => m.code === titularMem?.modalityCode && m.code !== 'SEM_PLANO') ||
          (state.modalities && state.modalities.length > 0 ? state.modalities[0] : null);

        const modCode = mod?.code || (isTitularFamilyPub ? 'PUBLICIDADE' : titularMem?.modalityCode) || 'ADULTO';
        const modName =
          modCode === 'PUBLICIDADE'
            ? (titularMem?.modalityName && !/^sem plano$/i.test(titularMem.modalityName) ? titularMem.modalityName : 'Lessa Family Publicidade')
            : (mod?.name && !/^sem plano$/i.test(mod.name) ? mod.name : (titularMem?.modalityName || targetSub.planSummaryLabel || 'Lessa Club'));
        const frontCard =
          modCode === 'PUBLICIDADE'
            ? '/cards/30.png'
            : (mod?.dependentFrontCardUrl || mod?.frontCardUrl || titularMem?.frontCardUrl || '/cards/44.png');
        const backCard =
          modCode === 'PUBLICIDADE'
            ? '/cards/33.png'
            : (mod?.dependentBackCardUrl || mod?.backCardUrl || titularMem?.backCardUrl || '/cards/24.png');

        const inheritedStatus: SubscriptionStatus =
          targetSub.status === 'INACTIVE' || targetSub.status === 'SUSPENDED' || targetSub.status === 'CANCELLED'
            ? targetSub.status
            : targetSub.status === 'ACTIVE'
            ? 'ACTIVE'
            : 'PENDING_TRANSFER';

        const newMember: ClubMember = {
          id: `mem-${cardNum}-${Date.now()}-${i}`,
          subscriptionId: targetSub.id,
          role: 'DEPENDENTE',
          modalityCode: modCode,
          modalityName: modName,
          planCycleLabel: modName,
          fullName: cleanName,
          cpf: cleanCpf,
          birthDate: person.birthDate || '',
          phone: person.phone || '',
          cardNumber: cardNum,
          holderCardNumber: targetSub.subscriptionCode,
          qrToken: `LC-${cardNum}`,
          frontCardUrl: frontCard,
          backCardUrl: backCard,
          validityLabel: getValidityLabelFromDate(targetSub.endDate),
          expirationDate: targetSub.endDate,
          monthlyValue: 0,
          status: inheritedStatus,
          inactivityReason: inheritedStatus !== 'ACTIVE' ? targetSub.inactivityReason : undefined,
          inactivityReasons: inheritedStatus !== 'ACTIVE' ? targetSub.inactivityReasons : undefined,
          inactivityNotes: inheritedStatus !== 'ACTIVE' ? targetSub.inactivityNotes : undefined,
          documentVerified: false,
          manualStatusOverride: true,
          createdAt: new Date().toISOString(),
        };

        currentMembers.push(newMember);
        addedNames.push(cleanName);

        if (person.sourceSubscriptionId && person.sourceSubscriptionId !== targetSub.id) {
          const sourceSub = nextSubs.find((s) => s.id === person.sourceSubscriptionId);
          if (sourceSub) {
            if (sourceSub.members.length <= 1) {
              // Era uma assinatura solitária só dessa pessoa -> removemos o registro solto
              nextSubs = nextSubs.filter((s) => s.id !== person.sourceSubscriptionId);
              if (!nextDeleted.includes(person.sourceSubscriptionId)) {
                nextDeleted.push(person.sourceSubscriptionId);
              }
            } else {
              // Tinha outros membros -> remove apenas essa pessoa da assinatura de origem
              nextSubs = nextSubs.map((s) =>
                s.id === person.sourceSubscriptionId
                  ? {
                      ...s,
                      members: s.members.filter(
                        (m) =>
                          m.cardNumber !== cardNum &&
                          m.fullName.trim().toLowerCase() !== cleanName.toLowerCase()
                      ),
                    }
                  : s
              );
            }
          }
        }
      }

      if (addedNames.length === 0) {
        toast({
          title: 'Nenhum dependente novo adicionado',
          description: 'A(s) pessoa(s) selecionada(s) já faz(em) parte deste cadastro.',
          variant: 'destructive',
        });
        setAttachingPersonLoading(false);
        return;
      }

      const updatedTargetSub: ClubSubscription = {
        ...targetSub,
        members: currentMembers,
        updatedAt: new Date().toISOString(),
        isModifiedFromSeed: true,
        manualStatusOverride: true,
      };

      nextSubs = nextSubs.map((s) => (s.id === updatedTargetSub.id ? updatedTargetSub : s));

      const nextState: ClubDatabaseState = {
        ...state,
        subscriptions: nextSubs,
        deletedSubscriptionIds: nextDeleted,
      };

      await persist(nextState);
      const permCode = updatedTargetSub.subscriptionCode || updatedTargetSub.holderCpf;
      if (permCode) {
        saveMemberPermanentDocs(permCode, updatedTargetSub).catch(() => {});
      }
      setSelectedSubForDetail(updatedTargetSub);
      setSelectedPersonsMap({});
      setPersonSearchModalOpen(false);
      setPersonSearchQuery('');

      toast({
        title: `${addedNames.length} Dependente(s) Agrupado(s) com Sucesso!`,
        description: `${addedNames.join(', ')} vinculado(s) à família de ${targetSub.holderName}.`,
      });
    } catch (err) {
      console.error('Erro ao agrupar dependentes:', err);
      toast({
        title: 'Erro ao agrupar dependente(s)',
        description: 'Ocorreu uma falha ao vincular a pessoa. Tente novamente.',
        variant: 'destructive',
      });
    } finally {
      setAttachingPersonLoading(false);
    }
  };

  // Função para vincular 1 pessoa diretamente
  const handleAttachPersonAsDependent = async (person: {
    fullName: string;
    cpf?: string;
    cardNumber?: string;
    birthDate?: string;
    phone?: string;
    modalityCode?: string;
    sourceSubscriptionId?: string;
  }) => {
    return handleAttachMultiplePersonsAsDependents([person]);
  };

  // Transferir uma assinatura individual (ex: Kids, PCD/TEA, Vitalício ou avulsa) como dependente para um titular
  const handleTransferSubAsDependentToTitular = async (
    sourceSub: ClubSubscription,
    targetTitularSub: ClubSubscription
  ) => {
    if (!state) return;
    setIsTransferringToHolder(true);

    try {
      const sourceMember =
        sourceSub.members.find((m) => m.role === 'TITULAR') ||
        sourceSub.members[0];

      const cardNum =
        sourceMember?.cardNumber ||
        sourceSub.subscriptionCode ||
        String(Date.now());

      const cleanName = (sourceMember?.fullName || sourceSub.holderName).trim();
      const cleanCpf = sourceMember?.cpf ? formatCpf(sourceMember.cpf) : sourceSub.holderCpf ? formatCpf(sourceSub.holderCpf) : '';

      // Identifica o plano e modalidade correta (se for "Sem Plano", herda automaticamente do titular!)
      const rawPlan = sourceSub.planSummaryLabel || sourceMember?.modalityName || '';
      const detectedCodeRaw = detectModalityCodeFromPlanDescription(
        rawPlan,
        sourceMember?.modalityCode,
        state.modalities
      );
      const titularMemTarget = targetTitularSub.members.find((m) => m.role === 'TITULAR') || targetTitularSub.members[0];
      const isSourceSemPlano =
        !detectedCodeRaw ||
        detectedCodeRaw === 'SEM_PLANO' ||
        /^sem plano$/i.test(rawPlan.trim()) ||
        rawPlan.trim() === '-' ||
        rawPlan.trim() === '- R$ 0,00';
      const isTitularFamilyPub =
        targetTitularSub.contractType === 'FAMILY_PUBLICIDADE' ||
        titularMemTarget?.modalityCode === 'PUBLICIDADE' ||
        Boolean(targetTitularSub.planSummaryLabel && /publicidade|family/i.test(targetTitularSub.planSummaryLabel));

      const detectedCode = isSourceSemPlano
        ? (isTitularFamilyPub ? 'PUBLICIDADE' : (titularMemTarget?.modalityCode && titularMemTarget.modalityCode !== 'SEM_PLANO' ? titularMemTarget.modalityCode : 'ADULTO'))
        : detectedCodeRaw;

      const chosenModality =
        (state.modalities || []).find((m) => m.code === detectedCode) ||
        (state.modalities || []).find((m) => m.code === titularMemTarget?.modalityCode && m.code !== 'SEM_PLANO');

      const modCode = chosenModality?.code || detectedCode || 'ADULTO';
      const modName =
        modCode === 'PUBLICIDADE'
          ? (titularMemTarget?.modalityName && !/^sem plano$/i.test(titularMemTarget.modalityName) ? titularMemTarget.modalityName : 'Lessa Family Publicidade')
          : (chosenModality?.name && !/^sem plano$/i.test(chosenModality.name) ? chosenModality.name : (titularMemTarget?.modalityName || 'Lessa Club'));

      let frontCard =
        modCode === 'PUBLICIDADE'
          ? '/cards/30.png'
          : (chosenModality?.dependentFrontCardUrl ||
            chosenModality?.frontCardUrl ||
            sourceMember?.frontCardUrl);
      let backCard =
        modCode === 'PUBLICIDADE'
          ? '/cards/33.png'
          : (chosenModality?.dependentBackCardUrl ||
            chosenModality?.backCardUrl ||
            sourceMember?.backCardUrl);

      if (!frontCard || frontCard === '/cards/44.png' || frontCard === '/cards/13.png') {
        if (modCode === 'KIDS') frontCard = '/cards/38.png';
        else if (modCode === 'PCD_TEA') frontCard = '/cards/35.png';
        else if (modCode === 'IDOSO_60') frontCard = '/cards/26.png';
        else if (modCode === 'PUBLICIDADE') frontCard = '/cards/30.png';
        else frontCard = '/cards/44.png';
      }

      if (!backCard) {
        if (modCode === 'KIDS' || modCode === 'IDOSO_60') backCard = '/cards/39.png';
        else if (modCode === 'PUBLICIDADE') backCard = '/cards/33.png';
        else backCard = '/cards/24.png';
      }

      const inheritedDepStatus: SubscriptionStatus =
        targetTitularSub.status === 'INACTIVE' || targetTitularSub.status === 'SUSPENDED' || targetTitularSub.status === 'CANCELLED'
          ? targetTitularSub.status
          : targetTitularSub.status === 'ACTIVE'
          ? 'ACTIVE'
          : 'PENDING_TRANSFER';

      const newDependentMember: ClubMember = {
        id: sourceMember?.id || `mem-${cardNum}-${Date.now()}`,
        subscriptionId: targetTitularSub.id,
        role: 'DEPENDENTE',
        modalityCode: modCode,
        modalityName: modName,
        planCycleLabel: modName,
        fullName: cleanName,
        cpf: cleanCpf,
        rg: sourceMember?.rg || sourceSub.holderRg || '',
        birthDate: sourceMember?.birthDate || sourceSub.holderBirthDate || '',
        sex: sourceMember?.sex || sourceSub.holderSex,
        phone: sourceMember?.phone || sourceSub.holderPhone || '',
        cardNumber: cardNum,
        holderCardNumber: targetTitularSub.subscriptionCode,
        qrToken: `LC-${cardNum}`,
        frontCardUrl: frontCard,
        backCardUrl: backCard,
        validityLabel: sourceMember?.validityLabel || getValidityLabelFromDate(targetTitularSub.endDate),
        expirationDate: sourceMember?.expirationDate || targetTitularSub.endDate,
        monthlyValue: 0,
        status: inheritedDepStatus,
        inactivityReason: inheritedDepStatus !== 'ACTIVE' ? targetTitularSub.inactivityReason : undefined,
        inactivityReasons: inheritedDepStatus !== 'ACTIVE' ? targetTitularSub.inactivityReasons : undefined,
        inactivityNotes: inheritedDepStatus !== 'ACTIVE' ? targetTitularSub.inactivityNotes : undefined,
        cardStatus: sourceMember?.cardStatus || 'NOT_PRODUCED',
        manualStatusOverride: true,
        proofDocuments: sourceMember?.proofDocuments || [],
        attachments: [
          ...(sourceMember?.attachments || []),
          ...(sourceSub.attachments || []),
        ],
        createdAt: sourceMember?.createdAt || new Date().toISOString(),
      };

      const currentMembers = targetTitularSub.members.filter(
        (m) =>
          m.cardNumber !== cardNum &&
          m.id !== newDependentMember.id &&
          (!cleanCpf || !m.cpf || m.cpf.replace(/\D/g, '') !== cleanCpf.replace(/\D/g, ''))
      );

      const updatedTargetMembers = [...currentMembers, newDependentMember];

      const updatedTargetSub: ClubSubscription = {
        ...targetTitularSub,
        members: updatedTargetMembers,
        updatedAt: new Date().toISOString(),
        isModifiedFromSeed: true,
        manualStatusOverride: true,
      };

      const nextSubs = (state.subscriptions || [])
        .filter((s) => s.id !== sourceSub.id)
        .map((s) => (s.id === updatedTargetSub.id ? updatedTargetSub : s));

      const nextDeleted = Array.from(
        new Set([...(state.deletedSubscriptionIds || []), sourceSub.id])
      );

      const nextState: ClubDatabaseState = {
        ...state,
        subscriptions: nextSubs,
        deletedSubscriptionIds: nextDeleted,
      };

      await persist(nextState);
      const permCode = updatedTargetSub.subscriptionCode || updatedTargetSub.holderCpf;
      if (permCode) {
        saveMemberPermanentDocs(permCode, updatedTargetSub).catch(() => {});
      }

      setSelectedSubForDetail(updatedTargetSub);
      setTransferHolderModalOpen(false);
      setTransferHolderSearchQuery('');

      toast({
        title: 'Associado transferido com sucesso!',
        description: `${newDependentMember.fullName} (#${cardNum} • ${modName}) agora faz parte da família de ${targetTitularSub.holderName}.`,
      });
    } catch (err: any) {
      console.error('[AdminClubEcosystem] Erro ao transferir associado:', err);
      toast({
        title: 'Erro ao transferir associado',
        description: err?.message || 'Falha ao vincular dependente ao titular.',
        variant: 'destructive',
      });
    } finally {
      setIsTransferringToHolder(false);
    }
  };

  // Desvincular um dependente e torná-lo titular de seu próprio cadastro individual
  const handleDetachDependentToIndividual = async (
    sub: ClubSubscription,
    memberId: string
  ) => {
    if (!state) return;
    const targetMember = sub.members.find((m) => m.id === memberId);
    if (!targetMember) return;

    const depCard = targetMember.cardNumber || String(Date.now());
    const newIndSub: ClubSubscription = {
      id: `sub-labcard-${depCard}`,
      subscriptionCode: depCard,
      personType: 'PF',
      holderName: targetMember.fullName,
      holderCpf: targetMember.cpf || '',
      holderBirthDate: targetMember.birthDate || '',
      holderPhone: targetMember.phone || '',
      addressCity: sub.addressCity || 'Porto Velho',
      addressState: sub.addressState || 'RO',
      billingCycle: 'MONTHLY',
      paymentMethod: 'PIX',
      installments: 1,
      monthlyEquivalent: 0,
      totalContractValue: 0,
      dueDay: 10,
      status: targetMember.status === 'ACTIVE' ? 'ACTIVE' : 'PENDING_TRANSFER',
      origin: sub.origin || 'IMPORT_LABCARD',
      planSummaryLabel: 'Sem Plano - R$ 0,00',
      notes: `Cadastro individual desvinculado de ${sub.holderName} (#${sub.subscriptionCode})`,
      contractType: 'ADESAO_PF',
      contractAccepted: true,
      startDate: sub.startDate || '2025-01-01',
      endDate: targetMember.expirationDate || sub.endDate || '2027-10-31',
      manualStatusOverride: true,
      transferCompleted: true,
      transferredAt: new Date().toISOString(),
      members: [
        {
          ...targetMember,
          role: 'TITULAR',
          holderCardNumber: depCard,
          modalityCode: 'SEM_PLANO',
          modalityName: 'Sem Plano',
          planCycleLabel: 'Sem Plano',
          manualStatusOverride: true,
        },
      ],
      invoices: [],
      attachments: [],
      visits: [],
      additionalServices: [],
    };

    const remainingMembers = sub.members.filter((m) => m.id !== memberId);
    const updatedSub: ClubSubscription = {
      ...sub,
      members: remainingMembers,
      updatedAt: new Date().toISOString(),
      manualStatusOverride: true,
      transferCompleted: true,
      transferredAt: sub.transferredAt || new Date().toISOString(),
    };

    let nextSubs = (state.subscriptions || []).map((s) =>
      s.id === updatedSub.id ? updatedSub : s
    );
    if (!nextSubs.some((s) => s.id === newIndSub.id)) {
      nextSubs.push(newIndSub);
    }

    const nextDeleted = (state.deletedSubscriptionIds || []).filter((id) => id !== newIndSub.id);
    const nextState: ClubDatabaseState = {
      ...state,
      subscriptions: nextSubs,
      deletedSubscriptionIds: nextDeleted,
    };

    await persist(nextState);
    if (selectedSubForDetail?.id === updatedSub.id) {
      setSelectedSubForDetail(updatedSub);
    }
    toast({
      title: 'Dependente Desvinculado!',
      description: `${targetMember.fullName} (Cartão #${depCard}) agora possui seu próprio cadastro individual como Titular.`,
    });
  };

  // Alterna manualmente o status de transferência concluída do associado
  const handleToggleTransferCompleted = async (sub: ClubSubscription, completed: boolean) => {
    if (!state) return;
    const isLab = sub.origin === 'IMPORT_LABCARD' || sub.id.startsWith('sub-labcard-');
    const isSameSelected = selectedSubForDetail?.id === sub.id;

    // Obedece estritamente o status principal definido pelo admin (INACTIVE, SUSPENDED, CANCELLED ou ACTIVE):
    // Se o cliente foi configurado como INATIVO pelo admin (no cadastro ou no seletor da tela),
    // concluir a transferência JAMAIS pode reativá-lo compulsoriamente.
    const isAdminInactive =
      sub.status === 'INACTIVE' ||
      sub.status === 'SUSPENDED' ||
      sub.status === 'CANCELLED' ||
      Boolean(sub.inactivityReason) ||
      (isSameSelected && situacaoInativar === 'SIM' && situacaoLiberar === 'NAO');

    const preservedInactiveStatus: SubscriptionStatus =
      sub.status === 'SUSPENDED' || sub.status === 'CANCELLED' ? sub.status : 'INACTIVE';

    const targetStatus: SubscriptionStatus = completed
      ? (isAdminInactive
          ? preservedInactiveStatus
          : sub.status === 'PENDING_TRANSFER'
          ? 'ACTIVE'
          : sub.status)
      : (sub.status === 'ACTIVE' && isLab ? 'PENDING_TRANSFER' : sub.status);

    // Só registra como cartão ativo confirmado pelo admin se o status resultante for efetivamente ACTIVE
    markCardAsAdminConfirmed(sub.subscriptionCode, completed && targetStatus === 'ACTIVE');

    const effectiveInactivityReason =
      targetStatus !== 'ACTIVE'
        ? (sub.inactivityReason || (isSameSelected ? situacaoMotivoInativo : undefined) || 'FALTA_DOCUMENTOS')
        : undefined;
    const effectiveInactivityReasons =
      targetStatus !== 'ACTIVE'
        ? (sub.inactivityReasons && sub.inactivityReasons.length > 0
            ? sub.inactivityReasons
            : isSameSelected && situacaoMotivosInativo.length > 0
            ? situacaoMotivosInativo
            : effectiveInactivityReason
            ? [effectiveInactivityReason]
            : undefined)
        : undefined;

    const updatedSub: ClubSubscription = {
      ...sub,
      transferCompleted: completed,
      manuallyConfirmedTransfer: completed,
      transferredAt: completed ? (sub.transferredAt || new Date().toISOString()) : undefined,
      manualStatusOverride: true,
      isModifiedFromSeed: true,
      status: targetStatus,
      inactivityReason: effectiveInactivityReason,
      inactivityReasons: effectiveInactivityReasons,
      members: (sub.members || []).map((m) => {
        const hasRealDoc = memberHasProofUploaded(m, sub);
        const keepDocVerified = hasRealDoc && Boolean(m.documentVerified);
        return {
          ...m,
          status: completed
            ? (targetStatus === 'INACTIVE' || targetStatus === 'SUSPENDED' || targetStatus === 'CANCELLED'
                ? targetStatus
                : m.status === 'PENDING_TRANSFER'
                ? targetStatus
                : m.status)
            : (m.status === 'ACTIVE' && isLab ? 'PENDING_TRANSFER' : m.status),
          inactivityReason: targetStatus !== 'ACTIVE' ? (m.inactivityReason || effectiveInactivityReason) : undefined,
          inactivityReasons: targetStatus !== 'ACTIVE' ? (m.inactivityReasons || effectiveInactivityReasons) : undefined,
          manualStatusOverride: true,
          // JAMAIS marca documento como aprovado pelo admin se não houver anexo real enviado!
          documentVerified: keepDocVerified,
          documentStatus: keepDocVerified ? ('APROVADO' as const) : (hasRealDoc ? m.documentStatus : undefined),
        };
      }),
      updatedAt: new Date().toISOString(),
    };

    const nextSubs = (state.subscriptions || []).map((s) => (s.id === updatedSub.id ? updatedSub : s));
    const nextState: ClubDatabaseState = {
      ...state,
      subscriptions: nextSubs,
    };

    if (selectedSubForDetail?.id === updatedSub.id) {
      setSelectedSubForDetail(updatedSub);
    }

    await persist(nextState, { waitForCloud: true });

    const permCode = updatedSub.subscriptionCode || updatedSub.holderCpf;
    if (permCode) {
      saveMemberPermanentDocs(permCode, updatedSub).catch(() => {});
    }

    const statusBadgeText =
      targetStatus === 'ACTIVE'
        ? 'ATIVO (LIBERADO)'
        : targetStatus === 'INACTIVE'
        ? 'INATIVO'
        : targetStatus === 'SUSPENDED'
        ? 'SUSPENSO'
        : targetStatus === 'CANCELLED'
        ? 'CANCELADO'
        : targetStatus;

    toast({
      title: completed ? 'Transferência Concluída!' : 'Transferência Reaberta',
      description: completed
        ? targetStatus === 'ACTIVE'
          ? `O cadastro de ${updatedSub.holderName} foi conferido, regularizado e liberado no portal.`
          : `Transferência de ${updatedSub.holderName} concluída! O status ${statusBadgeText} configurado pelo administrador foi estritamente mantido.`
        : `O cadastro de ${updatedSub.holderName} retornou ao status de Pendente para Transferência/Conferência.`,
    });
  };

  const getSubscriptionPlanBreakdown = (sub: ClubSubscription) => {
    const members = Array.isArray(sub.members) ? sub.members : [];
    const items = members.map((m) => {
      const mod = (state?.modalities || []).find(
        (md) => md.code === m.modalityCode || md.name === m.modalityName
      );
      const planStr = (m.planCycleLabel || m.modalityName || sub.planSummaryLabel || '').toLowerCase();
      let monthly = 0;
      if (planStr.includes('3 pessoas') || planStr.includes('3 vidas')) {
        monthly = 149.70;
      } else if (planStr.includes('2 pessoas') || planStr.includes('2 vidas')) {
        monthly = 99.80;
      } else if (planStr.includes('4 pessoas') || planStr.includes('4 vidas')) {
        monthly = 199.60;
      } else if (planStr.includes('5 pessoas') || planStr.includes('5 vidas')) {
        monthly = 249.50;
      } else if (typeof m.monthlyValue === 'number' && Number.isFinite(m.monthlyValue) && m.monthlyValue >= 0) {
        monthly = m.monthlyValue;
      } else if (mod && !mod.isFreeTier) {
        monthly =
          sub.billingCycle === 'ANNUAL'
            ? Number(mod.annualInstallment ?? mod.monthlyPrice) || 0
            : Number(mod.monthlyPrice) || 0;
      }
      return {
        memberId: m.id,
        role: m.role,
        fullName: m.fullName,
        modalityName: m.modalityName || m.planCycleLabel || 'Plano',
        monthlyValue: Number(monthly.toFixed(2)),
      };
    });
    const sumFromMembers = Number(
      items.reduce((acc, item) => acc + item.monthlyValue, 0).toFixed(2)
    );
    const fallbackTotal =
      typeof sub.monthlyEquivalent === 'number' && Number.isFinite(sub.monthlyEquivalent) && sub.monthlyEquivalent >= 0
        ? Number(sub.monthlyEquivalent.toFixed(2))
        : 0;
    return {
      items,
      total: items.length > 0 ? sumFromMembers : fallbackTotal,
    };
  };

  const getSubscriptionPlanMonthlyTotal = (sub: ClubSubscription): number => {
    return getSubscriptionPlanBreakdown(sub).total;
  };

  const buildSafeMonthlyDueDate = (baseDate: Date, monthOffset: number, preferredDay: number): Date => {
    const candidateMonth = new Date(baseDate.getFullYear(), baseDate.getMonth() + monthOffset, 1, 12, 0, 0);
    const lastDay = new Date(candidateMonth.getFullYear(), candidateMonth.getMonth() + 1, 0).getDate();
    candidateMonth.setDate(Math.min(Math.max(1, preferredDay), lastDay));
    return candidateMonth;
  };

  const handleGenerateNewCarneForClient = async (
    sub: ClubSubscription,
    count = 12,
    customValue?: number,
    firstMonthlyDueDateStr?: string,
    desc = 'Mensalidade',
    mode: 'append' | 'replace' = 'append',
    options?: {
      adhesionDueDateStr?: string;
      recurrenceMode?: 'NONE' | 'REGISTERED_CARD';
      emitInAsaas?: boolean;
    }
  ) => {
    if (!state) return;
    const planCalculatedVal = getSubscriptionPlanMonthlyTotal(sub);
    const monthlyVal =
      typeof customValue === 'number' && Number.isFinite(customValue) && customValue >= 0
        ? Number(customValue.toFixed(2))
        : planCalculatedVal;

    const todayStr = new Date().toISOString().split('T')[0];
    const adhesionDate = new Date(`${options?.adhesionDueDateStr || firstMonthlyDueDateStr || todayStr}T12:00:00`);
    const firstMonthlyDate = new Date(`${firstMonthlyDueDateStr || todayStr}T12:00:00`);
    const existingGroups = (sub.invoices || [])
      .filter((i) => !isClubInvoiceReservation(i) && Number(i.carneGroup) !== 99)
      .map((i) => Number(i.carneGroup) || 1);
    const nextCarneGroup = existingGroups.length > 0 && mode === 'append' ? Math.max(...existingGroups) + 1 : 1;

    const startIndex = mode === 'append' ? sub.invoices.length : 0;
    const totalInst = count;
    const hasRegisteredCard = Boolean(sub.registeredCard?.last4Digits);
    const useCardRecurrence = options?.recurrenceMode === 'REGISTERED_CARD' && hasRegisteredCard;
    const invPaymentMethod: ClubPaymentMethod = useCardRecurrence
      ? sub.registeredCard?.cardType === 'DEBIT'
        ? 'DEBIT_CARD'
        : 'CREDIT_CARD'
      : sub.paymentMethod;

    const nowIso = new Date().toISOString();
    const newInvoices: ClubInvoice[] = Array.from({ length: count }, (_, idx) => {
      const due =
        idx === 0 && options?.adhesionDueDateStr
          ? adhesionDate
          : buildSafeMonthlyDueDate(
              firstMonthlyDate,
              options?.adhesionDueDateStr ? Math.max(0, idx - 1) : idx,
              firstMonthlyDate.getDate() || sub.dueDay || 10
            );
      const yyyy = due.getFullYear();
      const mm = String(due.getMonth() + 1).padStart(2, '0');
      const dd = String(due.getDate()).padStart(2, '0');
      const installmentNum = idx + 1;
      const isAdhesionFirst = count > 1 && idx === 0 && Boolean(options?.adhesionDueDateStr);
      return {
        id: `inv_${Date.now()}_${startIndex + installmentNum}`,
        subscriptionId: sub.id,
        subscriptionCode: sub.subscriptionCode,
        holderName: sub.holderName,
        holderCpf: sub.holderCpf,
        holderPhone: sub.holderPhone,
        installmentNumber: installmentNum,
        totalInstallments: totalInst,
        referenceMonth: `${mm}/${yyyy}`,
        amount: monthlyVal,
        dueDate: `${yyyy}-${mm}-${dd}`,
        paymentMethod: invPaymentMethod,
        status: 'PENDING',
        description: isAdhesionFirst ? `${desc} (1ª Parcela)` : desc,
        carneGroup: nextCarneGroup,
        invoiceKind: 'MENSALIDADE',
        createdAt: nowIso,
      };
    });

    const finalInvoices =
      mode === 'append' ? [...sub.invoices, ...newInvoices] : newInvoices;
    const updatedSub: ClubSubscription = {
      ...sub,
      monthlyEquivalent:
        mode === 'replace' || !sub.monthlyEquivalent ? monthlyVal : sub.monthlyEquivalent,
      totalContractValue:
        mode === 'replace' || !sub.totalContractValue
          ? sub.billingCycle === 'ANNUAL'
            ? Number((monthlyVal * 12).toFixed(2))
            : monthlyVal
          : sub.totalContractValue,
      paymentMethod: useCardRecurrence ? invPaymentMethod : sub.paymentMethod,
      invoices: finalInvoices,
      updatedAt: nowIso,
    };
    const nextState: ClubDatabaseState = {
      ...state,
      subscriptions: (state.subscriptions || []).map((s) =>
        s.id === updatedSub.id ? updatedSub : s
      ),
    };
    setSelectedSubForDetail(updatedSub);
    setSelectedCarneNumber(String(nextCarneGroup));
    await saveMemberPermanentDocs(updatedSub.subscriptionCode, updatedSub, 'ADMIN_CREATE_CARNE');
    await persist(nextState, { waitForCloud: true });

    if (options?.emitInAsaas && monthlyVal > 0) {
      try {
        const res = await emitCarneMonthlyChargesInAsaas({
          subscriptionId: updatedSub.id,
          invoiceIds: newInvoices.map((i) => i.id),
          billingType: useCardRecurrence ? 'UNDEFINED' : 'UNDEFINED',
          firstDueDate: newInvoices[0]?.dueDate,
          dueDay: firstMonthlyDate.getDate() || sub.dueDay || 10,
          activateCardRecurrence: useCardRecurrence,
          cardLast4: sub.registeredCard?.last4Digits,
        });
        setState(res.state);
        const syncedSub = res.state.subscriptions.find((s) => s.id === updatedSub.id);
        if (syncedSub) {
          setSelectedSubForDetail(syncedSub);
        }
        toast({
          title: `Carnê ${nextCarneGroup} criado e enviado ao Asaas!`,
          description: `${res.generatedCount} cobrança(s) emitida(s) de ${formatCurrency(monthlyVal)}${res.failedCount > 0 ? ` (${res.failedCount} não emitidas: ${res.firstError || 'verifique os dados'})` : ''}.`,
        });
        return syncedSub || updatedSub;
      } catch (err: any) {
        toast({
          title: `Carnê ${nextCarneGroup} salvo localmente`,
          description: `Não foi possível emitir no Asaas agora: ${err?.message || 'verifique o CPF/integração'}. Use "GERAR CARNÊ" depois para emitir no Asaas.`,
          variant: 'destructive',
        });
        return updatedSub;
      }
    }

    toast({
      title: `Carnê ${nextCarneGroup} gerado com sucesso!`,
      description: `${count} parcelas de ${formatCurrency(monthlyVal)} adicionadas para ${sub.holderName}.`,
    });
    return updatedSub;
  };

