                    const digitalSignLink = `${originUrl}/socio?cpf=${encodeURIComponent(
                      selectedSubForDetail.holderCpf
                    )}&cartao=${encodeURIComponent(
                      selectedSubForDetail.subscriptionCode
                    )}&assinar=1`;
                    const phoneDigits =
                      selectedSubForDetail.holderPhone.replace(/\D/g, '');
